package app.loveu;
import android.app.*;import android.content.*;import android.hardware.biometrics.BiometricPrompt;import android.hardware.fingerprint.FingerprintManager;import android.os.*;import android.security.keystore.*;import android.util.Base64;import org.json.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;
/** An auth-per-use Keystore token; enrollment changes invalidate the biometric key. */
final class BiometricUnlock {
 static final String ALIAS="loveu.biometric.v1";
 final MainActivity activity;CancellationSignal cancellation;int generation;
 interface Finished{void success();}
 BiometricUnlock(MainActivity a){activity=a;}
 boolean available(){try{FingerprintManager f=activity.getSystemService(FingerprintManager.class);return f!=null&&f.isHardwareDetected()&&f.hasEnrolledFingerprints();}catch(Exception e){return false;}}
 boolean enabled(){return activity.settings().optBoolean("biometricEnabled",false)&&activity.settings().has("pinHash");}
 void cancel(){generation++;if(cancellation!=null){cancellation.cancel();cancellation=null;}}
 void disable()throws Exception{synchronized(Vault.class){Vault v=new Vault(activity);JSONObject r=v.read(),s=r.getJSONObject("settings");for(String k:new String[]{"biometricEnabled","biometricCipher","biometricIv","biometricHash"})s.remove(k);v.write(r);activity.root=r;}KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))store.deleteEntry(ALIAS);cancel();}
 Cipher cipher(boolean setup)throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(setup){if(store.containsAlias(ALIAS))store.deleteEntry(ALIAS);KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");KeyGenParameterSpec.Builder spec=new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setUserAuthenticationRequired(true).setInvalidatedByBiometricEnrollment(true);if(Build.VERSION.SDK_INT>=30)spec.setUserAuthenticationParameters(0,KeyProperties.AUTH_BIOMETRIC_STRONG);generator.init(spec.build());generator.generateKey();}if(!store.containsAlias(ALIAS))throw new GeneralSecurityException("请用 PIN 解锁后重新开启指纹");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");if(setup)cipher.init(Cipher.ENCRYPT_MODE,store.getKey(ALIAS,null));else cipher.init(Cipher.DECRYPT_MODE,store.getKey(ALIAS,null),new GCMParameterSpec(128,Base64.decode(activity.settings().getString("biometricIv"),Base64.NO_WRAP)));return cipher;}
 void authenticate(boolean setup,Finished done){if(!available()){message("请先在手机设置中录入指纹");return;}cancel();final int request=++generation;try{final Cipher cipher=cipher(setup);cancellation=new CancellationSignal();
  if(Build.VERSION.SDK_INT>=28){BiometricPrompt.Builder builder=new BiometricPrompt.Builder(activity).setTitle(Language.ui(setup?"开启指纹解锁":"解锁 Love U")).setSubtitle(Language.ui("验证手机中已录入的指纹")).setNegativeButton(Language.ui("使用 PIN"),activity.getMainExecutor(),(d,w)->cancel());if(Build.VERSION.SDK_INT>=30)builder.setAllowedAuthenticators(android.hardware.biometrics.BiometricManager.Authenticators.BIOMETRIC_STRONG);builder.build().authenticate(new BiometricPrompt.CryptoObject(cipher),cancellation,activity.getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){if(r.getCryptoObject()!=null)complete(setup,r.getCryptoObject().getCipher(),request,done);}public void onAuthenticationError(int code,CharSequence error){if(request==generation){cancellation=null;if(code!=BiometricPrompt.BIOMETRIC_ERROR_USER_CANCELED&&code!=BiometricPrompt.BIOMETRIC_ERROR_CANCELED)message(error.toString());}}});}
  else {message("请触碰手机指纹传感器，或使用 PIN");activity.getSystemService(FingerprintManager.class).authenticate(new FingerprintManager.CryptoObject(cipher),cancellation,0,new FingerprintManager.AuthenticationCallback(){public void onAuthenticationSucceeded(FingerprintManager.AuthenticationResult r){if(r.getCryptoObject()!=null)complete(setup,r.getCryptoObject().getCipher(),request,done);}public void onAuthenticationError(int code,CharSequence error){if(request==generation){cancellation=null;message(error.toString());}}},new Handler(Looper.getMainLooper()));}
 }catch(Exception e){message("指纹暂不可用，请使用 PIN；可在解锁后重新开启指纹");}}
 void complete(boolean setup,Cipher cipher,int request,Finished done){if(request!=generation||!activity.resumed||activity.isFinishing())return;try{synchronized(Vault.class){Vault v=new Vault(activity);JSONObject r=v.read(),s=r.getJSONObject("settings");if(!s.has("pinHash"))throw new GeneralSecurityException("需要 PIN 备用解锁");if(setup){byte[] token=new byte[32];new SecureRandom().nextBytes(token);s.put("biometricCipher",Base64.encodeToString(cipher.doFinal(token),Base64.NO_WRAP));s.put("biometricIv",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP));s.put("biometricHash",Base64.encodeToString(MessageDigest.getInstance("SHA-256").digest(token),Base64.NO_WRAP));s.put("biometricEnabled",true);v.write(r);}else{if(!s.optBoolean("biometricEnabled"))return;byte[] plain=cipher.doFinal(Base64.decode(s.getString("biometricCipher"),Base64.NO_WRAP));if(!MessageDigest.isEqual(MessageDigest.getInstance("SHA-256").digest(plain),Base64.decode(s.getString("biometricHash"),Base64.NO_WRAP)))throw new GeneralSecurityException("Authentication token mismatch");}activity.root=r;}cancellation=null;done.success();}catch(Exception e){message("指纹解锁未完成，请使用 PIN");}}
 void message(String text){android.widget.Toast.makeText(activity,Language.ui(text),android.widget.Toast.LENGTH_LONG).show();}
}
